NAME = 'NorSMB: Studentmållagsbibelen frå 1921'
BOOK = 'Esther'

CHAPTERS = {
    1: {
        1: 'Det hende seg i styringstidi åt Ahasveros - som rådde frå India alt til Ætiopia yver eit hundrad og sju og tjuge jarlerike -',
        2: 'i dei dagarne då kong Ahasveros sat på kongsstolen i borgi Susan:',
        3: 'i det tridje styringsåret hans gjorde han eit gjestebod for alle hovdingarne og tenarane sine, medan heren frå Persia og Media var samla hjå honom, saman med storfolket og jarlarne.',
        4: 'I mange dagar, eit hundrad og åtteti dagar, synte han deim sin kongelege rikdom og herlegdom og stordom med all dramb og drust.',
        5: 'Då dei dagarne var lidne, gjorde kongen eit gjestebod i sju dagar for alt folket som fanst i borgi Susan, frå den høgste til den lægste, i den inngjerde hagen ved kongsborgi.',
        6: 'Der hekk tjeld av kvitt lin og bomull og purpurblått ty, feste med kvite og purpur-raude snorer til sylvringar på kvite marmorsulor. Der stod benkjer av gull sylv, på eit golv av grønt og kvitt marmor og perlemorstein og svart stein.',
        7: 'Drykkjerne vart skjenkte i gullstaup, kvart staup hadde sers skap. Og der var nøgdi av kongeleg vin, på kongevis.',
        8: 'Den fyresegni vart sett drikkingi, at ingen skulde nøydast; kongen hadde bode alle hovmeistrarne at dei skulde lata kvar mann få so mykje han sjølv hadde hug på.',
        9: 'Dronning Vasti gjorde samstundes eit gjestebod for kvinnorne i det kongelege huset åt kong Ahasveros.',
        10: 'Sjuande dagen då kongen var fjåg av vinen, baud han dei sju hirdmennerne som gjorde tenesta hjå kong Ahasveros: Mehuman, Bizta, Harbona, Bigta, og Abagta, Zetar og Karkas,',
        11: 'at dei skulde henta dronning Vasti og leida henne fram for kongen, med kongskruna på, so han kunde syna fram vænleiken hennar for folki og for hovdingarne; for ho var fager å sjå til.',
        12: 'Men dronning Vasti vilde ikkje koma, tråss i det kongsbodet hirdmennerne bar fram. Då vart kongen veldugt vreid, og harmen loga upp i honom.',
        13: 'Kongen sagde til vismennerne, dei som hadde vit på tiderne - soleis vart alle kongssakar framlagde for deim som hadde vit på lov og rett,',
        14: 'og dei som stod honom næmast, var Karsena, Setar, Admata, Tarsis, Meres, Marsena og Memukan, dei sju hovdingarne i Persia og Media, som stod kongen næmast, og åtte øvste sæti i riket -:',
        15: '«Kva skal det etter lovi gjerast med dronning Vasti, sidan ho ikkje lyder det bodet kong Ahasveros sende henne med hirdmennerne?»',
        16: 'Memukan tok til ords for kongen og hovdingarne: «Dronning Vasti hev ikkje berre forbrote seg mot kongen, men mot alle hovdingarne og alle folki i alle jarleriki åt kong Ahasveros.',
        17: 'Åtferdi hennar vil koma ut millom alle konorne, og vil føra til at dei vanvyrdar mennerne sine; for dei vil segja: «Kong Ahasveros baud at dei skulde føra dronning Vasti fram for honom, men ho kom ikkje!»',
        18: 'Ja, alt i dag vil hovdingfruorne i Persia og Media høyra gjete åtferdi til dronningi og svara alle kongens hovdingar sameleis, og det vil verta nok av vanvyrdnad og harm.',
        19: 'Tekkjest det kongen, so lat eit kongebod verta utferda, og uppskrive millom loverne i Persia og Media, so det stend uruggeleg fast, at Vasti skal aldri meir koma fram for kong Ahasveros; hennar kongelege stand gjev kongen til ei onnor, som er likare enn ho.',
        20: 'Når dette kongelege påbodet vert utferda og kunngjort i heile kongens rike, so vida det rekk, då vil alle konor syna mennerne sine æra, frå dei høgste til dei lægste.»',
        21: 'Dette ordet lika kongen og stormennerne godt, og kongen gjorde som Memukan hadde sagt.',
        22: 'Brev vart sende til alle jarledømi åt kongen, til kvart jarledøme med deira skrift og til kvart folk på deira tungemål: at kvar mann skulde vera herre i sitt hus, og tala sitt eige folkemål.',
    },
    2: {
        1: 'Etter ei tid var gjengi og sinne hadde runne av kong Ahasveros, tenkte han på Vasti, og åtferda hennar, og domen yver henne.',
        2: 'Hirdmennerne som gjorde tenesta hjå kongen, sagde då: «Lat folk leita upp åt kongen fagre ungmøyar!',
        3: 'Lat kongen setja folk i alle kongens jarlerike til å samla alle fagre ungmøyar til kvendehuset i borgi Susan under tilsyn av kongens hirdmann Hege, kvendevaktaren, so dei kann få det dei treng til å hama seg.',
        4: 'Den ungmøyi som kongen likar, ho skal då verta dronning i staden for Vasti.» Dette tykte kongen vel um, og han so gjorde.',
        5: 'I borgi Susan var det ein jøde som heitte Mordokai, son åt Ja’ir, son åt Sime’i, son åt Kis, av Benjamins-ætti.',
        6: 'Han var burtførd frå Jerusalem millom dei fangarne som vart burtførde saman med Juda-kongen Jekonja, dei som Babel-kongen Nebukadnessar førde burt.',
        7: 'Han var fosterfar åt Hadassa, som og heitte Ester, dotter åt farbror hans; ho åtte korkje far eller mor. Gjenta var velvaksi og væn. Og då foreldri hennar døydde, tok Mordokai henne til seg som si eigi dotter.',
        8: 'Då kongebodet og fyreseigni vart kunngjort, og dei samla saman mange ungmøyar i borgi Susan under tilsyn av Hegai, henta dei ogso Ester til kongshuset under tilsyn av kvendevaktaren Hegai.',
        9: 'Han lika gjenta godt og fann hugnad i henne. Difor skunda han seg å gjeva henne alt turvande til å hama seg, like eins gav han henne den maten ho skulde hava, og dei sju ternor ho skulde hava frå kongshuset. Han let henne og ternorne hennar flytja inn i beste romet i kvendehuset.',
        10: 'Ester gat ikkje eit ord um folket sitt eller ætti si; Mordokai hadde sagt henne fyre å tegja um det.',
        11: 'Kvar einaste dag gjekk Mordokai att og fram utanfor garden ved kvendehuset, han vilde få vita kor det stod til med Ester, og kor det gjekk henne.',
        12: 'Kvar ungmøy kom inn til kong Ahasveros etter tur. Det gjekk tolv månader til å stella med deim etter påbodet um kvendi: seks månader med myrra-olje, og seks månader med angande salvar og anna som kvende treng til å hama seg.',
        13: 'Når so ungmøyi gjekk inn til kongen, fekk ho med seg frå kvendehuset til kongshuset alt det ho ynskte.',
        14: 'Um kvelden gjekk ho inn; um morgonen gjekk ho attende, men då til eit anna kvendehus, under tilsyn av kongens hirdmann Sa’asgaz, vaktaren yver fylgjekonorne. Ho fekk då ikkje koma inn att til kongen, minder kongen lika henne so godt, at han sende bod etter henne med namns nemning.',
        15: 'Då radi kom til Ester, dotter åt Abiha’il, som var farbror åt Mordokai, fosterfar hennar, so kravde ho ikkje anna med seg enn det hirdmannen Hegai, kvendevaktaren, rådde til. Og alle som såg Ester, fann hugnad i henne.',
        16: 'Ester vart henta til kong Ahasveros i kongshuset hans i den tiande månaden, månaden tebet, i sjuande styringsåret hans.',
        17: 'Kongen vart gladare i Ester enn i alle dei andre kvendi; ho vann meir hugnad og godhug hjå honom enn alle dei andre ungmøyarne. Han sette kongskruna på hovudet hennar og gjorde henne til dronning i staden for Vasti.',
        18: 'Og kongen gjorde eit stort gjestebod for alle hovdingarne og tenarane sine, eit Ester-gjestebod, og han gav skattelette i alle jarleriki og gav gåvor med kongeleg raustleik.',
        19: 'Andre gongen samla dei saman ungmøyar, og Mordokai sat då kongsporten.',
        20: 'Ester hadde ikkje gjete ord um ætti si og folket sitt, etter pålegget frå Mordokai; Ester lydde framleides bodet hans Mordokai, like eins som då ho vart fostra hjå honom.',
        21: 'Den tid Mordokai sat i kongsporten, vart Bigtan og Teres, tvo konglege hirdmenner som heldt vakt ved dørstokken, harme og freista finne høve til å leggja hand på kong Ahasveros.',
        22: 'Mordokai fekk vita dette, og sagde det med dronning Ester; so nemde Ester det med kongen på Mordokais vegner.',
        23: 'Saki vart granska, og det viste seg at det var sant, og dei tvo vart hengde i ein galge. Dette vart uppskrive i krønikeboki for kongen.',
    },
    3: {
        1: 'Ei tid etter gjorde kong Ahasveros agagiten Haman Hammedatason stor og gav honom rang og sæte yver alle hovdingarne som var hjå honom.',
        2: 'Og alle kongens tenarar som var i kongsporten, fall på kne og kasta seg ned for Haman; so hadde kongen sagt fyre om honom. Men Mordokai fall ikkje på kne og kasta seg ikkje ned.',
        3: 'Kongens tenerar som var i kongsporten spurde Mordokai: «Kvifor gjer du imot kongens påbod?»',
        4: 'Dag etter dag kom dei med dette spørsmålet; men han høyrde ikkje på deim. So melde dei det for Haman, dei vilde sjå um den forklåring Mordokai gav, fekk gjelda; for han hadde fortalt deim at han var jøde.',
        5: 'Då Haman gådde at Mordokai ikkje fall på kne og ikkje kasta seg ned for honom, då vart han full av harm.',
        6: 'Men han tykte det var for lite å leggja hand på berre Mordokai. Dei hadde meldt kongen kva folk Mordokai høyrde til. Og so søkte Haman høve til å rydja ut alle jødar i heile riket åt Ahasveros, av di dei var landsmennerne hans Mordokai.',
        7: 'Fyrste månaden, månaden nisan, i tolvte styringsåret åt kong Ahasveros, kasta dei pur, det er lut, for Haman um kvar einskild dag og kvar einskild månad, alt til tolvte månaden, månaden adar.',
        8: 'Og Haman sagde til kong Ahasveros: «Her finst eit folk som bur spreidt og utskildt millom dei andre folki i alle jarledøme i riket ditt. Loverne deira er ulike loverne åt alle andre folk, og kongens lover held dei ikkje, so kongen kann ikkje lita seg med å lata deim i fred.',
        9: 'Tekkjest det kongen, so bør det verta utferda eit brev um å gjera ende på deim. Fem og tjuge tusund våger sylv kann eg då vega upp for embætsmennerne åt kongen til å leggja i kongens skattkammer.»',
        10: 'Kongen drog signetringen av handi si og gav Haman Hammedatason, agagiten, jødefienden.',
        11: '«Sylvet skal du få,» sagde kongen til Haman, «og med det folket kann du fara som du finn fyre.»',
        12: 'Då vart skrivarane åt kongen kalla saman, den trettande dagen i fyrste månaden, og dei skreiv i alle måtar soleis som Haman baud, til kongens satrapar, til jarlarne i kvar sitt jarlerike og til hovdingarne yver dei einskilde folki; kvart jarlerike fekk brevet med si skrift og kvart folk med sitt mål. I namnet åt kong Ahasveros ferda dei ut brevet og forsigla det med den kongelege signetringen.',
        13: 'So sende dei brev med snøggbod til alle jarleriki åt kongen, at alle jødar skulde verta utrudde, drepne og tynte, både unge og gamle, born og kvende, alle på ein dag, den trettande dagen i tolvte månaden, det vil segja månaden adar, og deira gods skulde gjevast til plundring.',
        14: 'I brevet stod at det skulde verta utferda ei lov og kunngjord for alle folk i kvart jarlerike, med bod um at dei skulde vera budde til den dagen.',
        15: 'Snøggbodi skunda seg av stad på kongens bod, so snart påbodet var gjeve i borgi Susan. Kongen og Haman sette seg til å drikka. Men byen Susan var reint forfjetra.',
    },
    4: {
        1: 'Då Mordokai fekk vita alt som var hendt, reiv han sund klædi sine og klædde seg i sekk og oska, gjekk ut i byen og skreik høgt og sårt.',
        2: 'Og han kom til plassen utanfor kongsporten; for ingen fekk lov til å ganga inn i kongsporten i syrgjebunad.',
        3: 'I kvart jarlerike, dit som kongens ord og påbod nådde, der vart det stor sorg millom jødar; dei fasta og gret og jamra; mange reidde upp under seg med sekk og oska.',
        4: 'Ternorne og hirdmennerne åt Ester kom og fortalde henne dette, og dronningi vart reint forstøkt. Ho sende klæde til Mordokai som han skulde taka på seg i staden for syrgjebunaden; men han tok ikkje imot.',
        5: 'Ester kalla då til seg Hatak, ein av kongens hirdmenner, som var sett til å tena henne, og sende honom til Mordokai til å få vita kva som var tids, og kvifor han bar seg soleis.',
        6: 'Hatak gjekk ut til Mordokai på bytorget under kongsporten.',
        7: 'Og Mordokai fortalde honom um alt det som hadde hendt honom, og nemnde grant den pengesumen som Haman hadde lova å vega upp åt kongskassa for jødarne, når han fekk tynt dei.',
        8: 'Dessutan gav han honom avskrift av det skrivne påbodet som hadde vorte utferda i Susan um å rydja deim ut; han skulde syna Ester det og melde henne det, og bjoda henne å ganga inn til kongen og beda um miskunn og søkja nåde for folket sitt hjå honom.',
        9: 'Hatak kom og melde Ester det Mordokai hadde sagt.',
        10: 'Då baud Ester Hatak ganga til Mordokai og segja:',
        11: '«Alle kongstenarane og folket i kongens jarlerike veit at den lovi gjeld for alle, kar eller kvende: gjeng nokon ukalla inn til kongen i den indre garden, so lyt han lata livet; det einaste er um kongen retter ut mot honom gullstaven, då fær han liva. Og eg hev ikkje vore kalla til kongen no på tretti dagar.»',
        12: 'Dei fortalde Mordokai kva Ester hadde sagt.',
        13: 'Då sagde Mordokai dei skulde svara henne: «Du må ikkje tenkja med deg sjølv at du skal sleppa undan millom alle jødar, av di er i huset hjå kongen.',
        14: 'Nei, tegjer du verkeleg stilt i dette høvet, so skal nok jødarne få utfriing og frelsa frå ein annan kant; men du og farshuset ditt skal ganga til grunnar. Kven veit um ikkje du hev nått til kongeleg rang just for dette høvet skuld?»',
        15: 'Då let Ester Mordokai få dette svaret:',
        16: '«Gakk og få saman alle jødar som finst i Susan, og haldt fasta for meg, so de korkje et eller drikk noko på tri døger, natt og dag. Eg og ternorne mine vil og fasta sameleis. Og so vil eg ganga inn til kongen, endå det er ulovlegt. Lyt eg so døy, so lat meg døy!»',
        17: 'Mordokai gjekk av stad og gjorde i alle måtar so som Ester hadde bode honom.',
    },
    5: {
        1: 'Tridje dagen klædde Ester seg i kongelegt skrud og gjekk inn i den indre garden til kongshuset midt fyre kongshuset, og kongen sat på kongsstolen sin i kongshalli, midt imot døri til huset.',
        2: 'Då kongen såg dronning Ester standa i garden, fann ho nåde i hans augo; og kongen rette ut til Ester gullstaven som han hadde i handi. Ester gjekk då fram og tok i enden av staven.',
        3: 'Kongen sagde til henne: «Kva hev du på hjarta, dronning Ester? kva er det du ynskjer? Um det so er helvti av riket, skal du få det.»',
        4: 'Ester svara: «Tekkjest det kongen, so må kongen saman med Haman koma i dag til det gjestebodet eg hev laga til åt honom.»',
        5: 'Kongen svara: «Skunda dykk, henta Haman, so me kann gjera det Ester bed um.» So kom då kongen og Haman til gjestebodet som Ester hadde laga til.',
        6: 'Då dei sat og drakk vin, spurde kongen Ester: «Kva er di bøn? Du skal få det du bed um! Og kva er ditt ynskje? Um det vore helvti av riket, so skal det løyvast deg!»',
        7: 'Ester svara: «Bøni mi og ynskjet mitt er:',
        8: 'Hev eg funne nåde i kongens augo, og det tekkjest kongen å gjeva meg det eg bed um og gjera det eg ynskjer, so må kongen og Haman koma til det gjestebodet eg vil laga til åt deim; so skal eg i morgon gjera som kongen segjer.»',
        9: 'Den dagen gjekk Haman derifrå glad og i godlag. Men då Haman fekk sjå Mordokai i kongsporten, og at han korkje reis upp eller synte nokon age for honom, då vart Haman full av harm mot Mordokai.',
        10: 'Like vel styrde han seg, til han kom heim. Då sende han bod etter venerne sine og etter Zeres, kona si.',
        11: 'Haman fortalde deim um all sin rikdom og herlegdom og um dei mange sønerne sine, og um alt det kongen hadde gjort til å gjera honom stor og setja honom høgre enn hovdingarne og kongens tenarar.',
        12: '«Ja, dronning Ester,» sagde han, «let ingen annan enn meg koma med kongen til det gjestebodet ho gjorde; til i morgon og hev ho bede meg saman med kongen.',
        13: 'Men alt dette kann eg ikkje lita meg med, so lenge eg ser jøden Mordokai sitja i kongsporten.»',
        14: 'Då sagde Zeres, kona hans, og venerne hans til honom: «Lat deim gjera ein galge, femti alner høg, og bed kongen i morgon um å få hengja Mordokai i den! So kann du fara glad til gjestebords med kongen.» Denne rådi lika Haman godt, og han let deim gjera galgen i stand.',
    },
    6: {
        1: 'Den natti flydde svevnen frå kongen. Han baud henta krønikeboki med minnelege hendingar, og ho vart upplesi for kongen.',
        2: 'Der fann dei uppskrive at Mordokai hadde meldt Bigtana og Teres, tvo hirdmenner hjå kongen som heldt vakt ved dørstokken, for dei hadde søkt høve til å leggja hand på kong Ahasveros.',
        3: 'So spurde kongen: «Kva æra og vyrdnad hev Mordokai fenge for dette?» Kongsdrengjerne som tente honom svara: «Han hev ingen ting fenge.»',
        4: 'So spurde kongen: «Kven er det som er ute i garden?» I det bilet var Haman komen inn i den ytre garden ved kongshuset, og vilde tala med kongen um å få hengt Mordokai i galgen han hadde reist åt honom.',
        5: 'Kongsdrengjerne svara: «Haman stend der ute i garden.» «Lat honom koma inn!» sagde kongen.',
        6: 'Då Haman kom inn, spurde kongen honom: «Korleis skal ein fara åt med den mannen som kongen gjerna vil heidra?» Haman tenkte med seg sjølv: «Kven skulde kongen vilja heidra meir enn meg?»',
        7: 'So svara han kongen: «Den som kongen gjerne vil heidra,',
        8: 'åt honom skal ein henta ein kongeleg klædnad som kongen sjølv hev bore, og ein hest som kongen sjølv hev ride på, og som hev fenge ei kongeleg kruna på hovudet,',
        9: 'klædnaden og hesten skal gjevast til ein av dei øvste stormennerne åt kongen, og dei skal hava klædnaden på den mannen kongen vil heidra og føra honom ridande på hesten fram på bytorget, og ropa framfyre honom: «Soleis gjer ein med den mannen som kongen vil heidra.»»',
        10: 'Då sagde kongen med Haman: «Skunda deg, tak klædnaden og hesten, som du hev sagt, og gjer soleis med jøden Mordokai som sit i kongsporten! Gløym ikkje noko av alt det du sagde!»',
        11: 'Haman tok klædnaden og hesten, hadde klædnaden på Mordokai, let honom rida fram på bytorget og ropa fyre honom: «Soleis gjer ein med den mannen som kongen vil heidra!»',
        12: 'Mordokai vende attende til kongsporten; men Haman skunda seg heim, sorgfull og med hovudet innsveipt.',
        13: 'Og Haman fortalde Zeres, kona si, og alle venerne sine alt det som hadde hendt honom. Då sagde vismennerne hans og Zeres, kona hans, med honom: «Um so er at Mordokai, som du tek til å liggja under for, er av jødeætt, so magtast du ingen ting mot honom; du kjem til å liggja reint under for honom.»',
        14: 'Medan dei endå tala med honom, kom hirdmennerne åt kongen og skulde snøggast henta Haman til gjestebodet som Ester hadde laga til.',
    },
    7: {
        1: 'So kom då kongen og Haman til drikkelaget hjå dronning Ester.',
        2: 'Då dei sat og drakk vin, spurde kongen Ester sameleis andre dagen: «Kva er di bøn, dronning Ester? Du skal få det du bed um. Kva er ditt ynskje? Um det vore helvti av riket, so skal det løyvast deg.»',
        3: 'Då svara dronning Ester: «Hev eg funne nåde i kongens augo, og det tekkjest kongen soleis, så unn meg mitt liv på mi bøn og mitt folk på mitt ynskje!',
        4: 'For me er selde, eg og folket mitt, til å verta utrudde, drepne og tynte. Hadde me vorte selde til trælar og trælkvinnor, då skulde eg tagt; for den ulukka vilde ikkje vore so stor at det var verdt å bry kongen.»',
        5: 'Då spurde kong Ahasveros dronning Ester: «Kven er han, og kvar er han, den som hev våga seg til å gjera sovore?»',
        6: 'Ester svara: «Det er ein illtenkt mann, ein fiendesmann, den vonde Haman, som sit der.» Då vart Haman forfærd for kongen og dronningi.',
        7: 'Kongen reis upp i harm frå drikkelaget og gjekk ut i slottshagen. Haman drygde, vilde tigga dronning Ester um livet; han skyna kongen var fast på å føra honom i ulukka.',
        8: 'Kongen kom attende til drikkelaget frå slottshagen og såg Haman liggja yver kvilebenken som Ester sat på. «Vil du,» ropa kongen, «jamvel her inne i mitt nærvære taka dronningi med vald?» Snaudt var ordi slopne utor munnen på kongen fyrr dei sveipte inn andlitet på Haman.',
        9: 'Harbona, ein av hirdmennerne som gjorde tenesta hjå kongen, sagde: «Attmed huset åt Haman stend det alt ein galge, femti alner høg; den let Haman reisa åt Mordokai, som med sine ord gjorde kongen gagn.» «Heng honom der!» sagde kongen.',
        10: 'So hengde dei Haman upp i den galgen han hadde reist åt Mordokai. Og kongens harm gav seg att.',
    },
    8: {
        1: 'Same dagen gav kong Ahasveros dronning Ester huset hans Haman, jødefienden, og Mordokai fekk koma inn til kongen; for Ester hadde fortalt kva han var for henne.',
        2: 'Kongen drog av seg signetringen som han hadde teke frå Haman, og gav honom til Mordokai. Og Ester sette Mordokai til å styra huset hans Haman.',
        3: 'Endå ein gong vende Ester seg til kongen, fall ned for føterne hans, gret og naudbad honom å gjera um inkje den ulukka og den meinrådi som agagiten Haman hadde etla jødarne.',
        4: 'Kongen rette gullstaven ut mot Ester. Då reis Ester upp og gjekk fram for kongen.',
        5: '«Tekkjest det kongen,» sagde ho, «og hev eg funne nåde i hans augo, tykkjer kongen det er meining i det, og held han meg gjæv, so lat det ferdast ut eit brev til avlysing av brevi med meinrådi åt agagiten Haman Hammedatason, dei som han ferda ut til å tyna jødarne i alle kongens jarlerike.',
        6: 'Kor skulda eg orka sjå på den ulukka som kjem yver folket mitt? Kor skulde eg orka sjå på at ætti mi vert tynt?»',
        7: 'Då sagde kong Ahasveros til dronning Ester og jøden Mordokai: «Sjå, eg hev gjeve Ester huset hans Haman, han sjølv er hengd i galgen, av di han vilde leggja hand på jødarne.',
        8: 'Ferda no de ut eit brev til jødarne i kongens namn, soleis som de tykkjer best, og forsigla det med signetringen åt kongen. For eit skriv som er utferda i kongens namn og forsigla med signetringen åt kongen, kann ikkje verta atterkalla.»',
        9: 'So vart då skrivarane åt kongen straks kalla saman, den tri og tjugande dagen i tridje månaden, månaden sivan, og dei skreiv i alle måtar soleis som Mordokai baud til jødarne og til satraparne og jarlarne og hovdingarne i jarleriki, frå India til Ætiopia, hundrad og sju og tjuge jarlerike; kvart rike fekk brevet med si skrift, kvart folk på sitt tungemål, og jødarne med si skrift og på sitt tungemål.',
        10: 'Han skreiv i namnet åt kong Ahasveros og forsigla med signetringen åt kongen. So sende han brev ikring med ridande snøggbod på tråvarar frå kongens eigne stallar,',
        11: 'at kongen gav jødarne i kvar by lov til å slå seg i hop og verja livet sitt, og rydja ut, drepa og tyna alle væpna flokkar i kvart folk og jarlerike som synte deim fiendskap, alt til born og kvende, og so plundra eigedomarne deira,',
        12: 'på ein og same dagen i alle jarleriki åt kong Ahasveros, trettande dagen i tolvte månaden, det vil segja månaden adar.',
        13: 'I brevet stod det at det skulde varta utferda ei lov og kunngjord for alle folk i kvart jarlerike: at jødarne skulde vera budde den dagen til å hemna seg på fiendarne sine.',
        14: 'Snøggbodi på dei konglege tråvarar reid av stad so fort dei kunde på kongens bod, so snart påbodet var utferda i borgi Susan.',
        15: 'Mordokai gjekk ut frå kongen i ein kongeleg klædnad av purpurblått og kvitt ty med ei stor gullkruna, og i ei kåpa av kvitt bomull og purpurraudt ty; og byen Susan jubla og gledde seg.',
        16: 'For jødarne rana no ljos og gleda, fagnad og vyrdnad.',
        17: 'Og i kvart jarlerike og i kvar ein by som kongens ord og påbod nådde til, der vart det gleda og fagnad på jødarne, med gilde og høgtid. Mange av folki i landet gjekk yver til jødedomen, so stor otte hadde dei fenge for jødarne.',
    },
    9: {
        1: 'Trettande dagen i den tolvte månaden, det vil segja månaden adar, den dagen det var fastsett at kongens ord og påbod skulde setjast i verk, den dagen jødefiendarne hadde vona å få magt yver deim - no hadde det snutt seg soleis, at det var jødarne som fekk magt yver fiendarne sine -',
        2: 'den dagen slo jødarne seg i hop i byarne sine i alle dei jarleriki åt kong Ahasveros og vilde leggja hand på deim som elta gjera deim mein. Og ingen stod seg imot deim; so stor otte hadde alle folk fenge for deim.',
        3: 'Alle hovdingarne i jarleriki og satraparne og jarlarne og embætsmennerne åt kongen hjelpte jødarne; so stor otte hadde dei fenge for Mordokai;',
        4: 'for Mordokai var ein stor mann i kongens hus; i alle jarleriki kom gjetord ut om honom, at denne Mordokai auka allstødt i magt.',
        5: 'Jødarne slo eit slag på alle fiendarne sine, med sverd og dreping og tyning, og dei for som dei vilde med motmennerne sine.',
        6: 'I borgi Susan drap og tynte jødarne fem hundrad mann.',
        7: 'Og Parsandata og Dalfon og Aspata',
        8: 'og Porata og Adalja og Aridata',
        9: 'og Parmasta og Arisai og Aridai og Vaizata,',
        10: 'dei ti sønerne åt Haman Hammedatason, jødefienden, drap dei. Men til plundring rette dei ikkje ut handi.',
        11: 'Same dagen høyrde kongen gjete talet på deim som var drepne i borgi Susan.',
        12: 'Då sagde kongen til dronning Ester: «I borgi Susan hev jødarne drepe og tynt fem hundrad mann forutan dei ti sønerne åt Haman. Kva hev dei so ikkje gjort i dei andre kongelege jarleriki? Kva er di bøn? Du skal få det du bed um! Og kva ynskje hev du meir? Det skal verta uppfyllt!»',
        13: 'Ester svara: «Tekkjest det kongen, so lat ogso i morgon jødarne i Susan få lov å gjera etter påbodet for i dag! Og lat dei ti sønerne åt Haman verta upphengde i galgen!»',
        14: 'Kongen baud at so skulde vera. Påbodet vart utferda i Susan. Alle ti sønerne åt Haman vart upphengde.',
        15: 'Jødarne i Susan slo seg i hop den fjortande dagen og i månaden adar og drap tri hundrad mann i Susan. Men til plundring rette dei ikkje ut handi.',
        16: 'Dei andre jødarne i jarleriki åt kongen slo seg i hop og varde livet og rådde seg ro for fiendarne sine. Dei drap fem og sytti tusund av motmennerne sine. Men til plundring rette dei ikkje ut handi.',
        17: 'Dette hende trettande dagen i månaden adar. Den fjortande kvilde dei ut og dei gjorde den dagen til ein gjestebodsdag og fagnad-dag.',
        18: 'Jødarne i Susan hadde slege seg i hop både trettande og fjortande dagen; dei kvilde ut den femtande og gjorde den dagen til gjestebodsdag og fagnad-dag.',
        19: 'Difor høgtidar jødarne på landsbygdi, dei som bur i landsbyarne, den fjortande dagen i månaden adar med fagnad, med gjestebod og festar og dei sender forner til kvarandre.',
        20: 'Mordokai skreiv upp desse hendingarne og sende brev til alle jødarne i alle jarleriki åt kong Ahasveros, nær og fjerr,',
        21: 'og slog fast for deim at dei år etter år skulde høgtida fjortande og femtande dagen i månaden adar,',
        22: 'for dei dagarne hadde jødarne rådt seg ro for fiendarne sine, og i den månaden hadde suti deira snutt seg um til fagnad og sorgi til høgtid. Difor skulde dei gjera desse dagarne til gjestebods-dagar og fagnad-dagar, og senda fornar til kvarandre og gåvor til fatigfolk.',
        23: 'Jødarne lovtok denne skikken, som dei no hadde teke til med, og som Mordokai hadde skrive til deim um.',
        24: 'Agagiten Haman Hammedatason, fienden åt alle jødar, hadde lagt upp råder mot jødarne um å tyna deim og hadde kasta pur, det er lut, for å øyda og tyna deim.',
        25: 'Men då kongen frette det, hadde han bode og ferda ut i eit brev um at meinråderne hans, som hin hadde etla åt jødarne, skulde snu attende på hans eige hovud, so han sjølv og sønerne hans vart hengde i galgen.',
        26: 'Av den grunn vart desse dagarne heitande purim, etter ordet pur. Og av den grunn - etter alt det som stod i dette brevet, etter det dei sjølve hadde set, og etter det som hadde hendt deim,',
        27: 'so gjorde jødarne det til fast skikk og bruk for seg og etterkomarane sine og for alle som gjekk yver til deira tru, at dei skulde år etter år, ubrigdeleg, høgtida desse tvo dagarne etter fyreskrifti um deim, og på den fastsette tidi,',
        28: 'og at desse dagarne skulde haldast i minne og høgtidast i alle aldrar og ætter og jarledøme og byar, og at desse purim-dagar ikkje måtte falla burt millom jødarne, og minnet um deim aldri kverva hjå etterkomarane deira.',
        29: 'Dronning Ester Abiha’ilsdotter og jøden Mordokai skreiv eit nytt brev med fynd og klemb og gjorde til lov det som stod i dette nye brevet um purim.',
        30: 'Og han sende brev til alle jødar i dei hundrad og sju og tjuge jarleriki i kongeriket åt Ahasveros, venlege og truhjarta ord',
        31: 'um å halda ved lag desse purim-dagarne på den fastsette tidi, soleis som jøden Mordokai og dronning Ester hadde bode deim, og soleis som dei hadde stadfest det for seg sjølve og etterkomarane sine, med fyresegner um fasta og klagerop.',
        32: 'Påbodet frå Ester gjorde desse purim-bodi til lov. Og dei vart uppskrive i ei bok.',
    },
    10: {
        1: 'Kong Ahasveros lagde skatt på upplandet på sjøbygderne.',
        2: 'Alt det han gjorde i si magt og sitt velde, og ei greinleg melding um den høge rang som kongen lyfte Mordokai upp til, det er uppskrive i krønikeboki åt dei mediske og persiske kongarne.',
        3: 'Jøden Mordokai var den som stod kong Ahasveros næmest, og han var stor millom jødarne og kjær for dei mange brørne sine; han søkte det som godt var for folket sitt, og tala til bate for all si ætt.',
    },
}
